goal.statement:
let p := ![p₀, p₁, p₂];
let β := ![0, p₀, p₀ + p₁];
let E := fun i => ∑' (k : ℕ), β (i k) * ∏ r ∈ Finset.range k, p (i r);
let canonical := fun x =>
  Classical.epsilon fun i => E i = x ∧ ((∃ j, E j = x ∧ j ≠ i) → ∃ N, ∀ (k : ℕ), N ≤ k → i k = 0);
let θ := ![0, 2, 1];
let f := fun x => E fun k => θ (canonical x k);
MeasureTheory.IntegrableOn f (Set.Icc 0 1) MeasureTheory.volume ∧
  ∫ (x : ℝ) in 0..1, f x = (p₁ ^ 2 + p₀ * p₁ + p₀ * p₂) / (1 - p₀ ^ 2 - 2 * p₁ * p₂)

